{-| @Pudu.Backend.Runtime.Tree — the balanced search tree behind every map and
    set. Nodes are shared between every tree that reached them, so an update
    copies the path it changes and keeps the rest. Every function takes the
    references it is handed and answers with one; keys passed only to be
    looked up are read, not taken. These parts use `pudu_cell`, so they are
    emitted after the frame types. -}
module Pudu.Backend.Runtime.Tree (treeRuntimeParts, treeRuntimeDependencies) where

import Data.Text (Text)

treeRuntimeParts :: [(Text, [Text])]
treeRuntimeParts =
  [ ("tree",
      [ "struct pudu_tree_node {"
      , "  size_t count;"
      , "  size_t size;"
      , "  int height;"
      , "  pudu_cell key;"
      , "  pudu_cell value;"
      , "  pudu_tree_node *left;"
      , "  pudu_tree_node *right;"
      , "};"
      , "/* What a tree needs to know about its key and value types. */"
      , "typedef struct {"
      , "  int (*order)(pudu_cell, pudu_cell);"
      , "  pudu_cell (*retain_key)(pudu_cell);"
      , "  void (*release_key)(pudu_cell);"
      , "  pudu_cell (*retain_value)(pudu_cell);"
      , "  void (*release_value)(pudu_cell);"
      , "} pudu_tree_ops;"
      , "static void pudu_tree_release(pudu_tree_node *node, const pudu_tree_ops *ops) {"
      , "  while (node != NULL && --node->count == 0) {"
      , "    pudu_tree_node *right = node->right;"
      , "    ops->release_key(node->key);"
      , "    ops->release_value(node->value);"
      , "    pudu_tree_release(node->left, ops);"
      , "    free(node);"
      , "    node = right;"
      , "  }"
      , "}"
      , "static inline size_t pudu_tree_size(const pudu_tree_node *node) { return node == NULL ? 0 : node->size; }"
      ])
  , ("tree_retain",
      [ "static inline pudu_tree_node *pudu_tree_retain(pudu_tree_node *node) {"
      , "  if (node != NULL) node->count += 1;"
      , "  return node;"
      , "}" ])
  , ("tree_node",
      [ "static inline int pudu_tree_height(const pudu_tree_node *node) { return node == NULL ? 0 : node->height; }"
      , "/* A node over two subtrees whose heights differ by two at most. */"
      , "static pudu_tree_node *pudu_tree_make(pudu_tree_node *left, pudu_cell key, pudu_cell value, pudu_tree_node *right) {"
      , "  pudu_tree_node *node = malloc(sizeof *node);"
      , "  int high_left = pudu_tree_height(left), high_right = pudu_tree_height(right);"
      , "  if (node == NULL) pudu_memory_failure();"
      , "  node->count = 1;"
      , "  node->size = pudu_tree_size(left) + pudu_tree_size(right) + 1;"
      , "  node->height = (high_left > high_right ? high_left : high_right) + 1;"
      , "  node->key = key;"
      , "  node->value = value;"
      , "  node->left = left;"
      , "  node->right = right;"
      , "  return node;"
      , "}"
      ])
  , ("tree_build",
      [ "/* Gives up node and hands back its parts. A node nobody else holds is taken"
      , "   apart; a shared one stays, and its parts are retained instead. */"
      , "static void pudu_tree_open(pudu_tree_node *node, const pudu_tree_ops *ops, pudu_tree_node **left, pudu_cell *key, pudu_cell *value, pudu_tree_node **right) {"
      , "  *left = node->left;"
      , "  *key = node->key;"
      , "  *value = node->value;"
      , "  *right = node->right;"
      , "  if (node->count == 1) { free(node); return; }"
      , "  node->count -= 1;"
      , "  pudu_tree_retain(*left);"
      , "  pudu_tree_retain(*right);"
      , "  *key = ops->retain_key(*key);"
      , "  *value = ops->retain_value(*value);"
      , "}"
      , "/* OCaml's Map.bal: subtrees may be three apart after one change; a single or"
      , "   double rotation brings them back within two. */"
      , "static pudu_tree_node *pudu_tree_balance(pudu_tree_node *left, pudu_cell key, pudu_cell value, pudu_tree_node *right, const pudu_tree_ops *ops) {"
      , "  int high_left = pudu_tree_height(left), high_right = pudu_tree_height(right);"
      , "  pudu_tree_node *outer, *inner, *inner_left, *inner_right;"
      , "  pudu_cell side_key, side_value, inner_key, inner_value;"
      , "  if (high_left > high_right + 2) {"
      , "    pudu_tree_open(left, ops, &outer, &side_key, &side_value, &inner);"
      , "    if (pudu_tree_height(outer) >= pudu_tree_height(inner))"
      , "      return pudu_tree_make(outer, side_key, side_value, pudu_tree_make(inner, key, value, right));"
      , "    pudu_tree_open(inner, ops, &inner_left, &inner_key, &inner_value, &inner_right);"
      , "    return pudu_tree_make(pudu_tree_make(outer, side_key, side_value, inner_left), inner_key, inner_value,"
      , "      pudu_tree_make(inner_right, key, value, right));"
      , "  }"
      , "  if (high_right > high_left + 2) {"
      , "    pudu_tree_open(right, ops, &inner, &side_key, &side_value, &outer);"
      , "    if (pudu_tree_height(outer) >= pudu_tree_height(inner))"
      , "      return pudu_tree_make(pudu_tree_make(left, key, value, inner), side_key, side_value, outer);"
      , "    pudu_tree_open(inner, ops, &inner_left, &inner_key, &inner_value, &inner_right);"
      , "    return pudu_tree_make(pudu_tree_make(left, key, value, inner_left), inner_key, inner_value,"
      , "      pudu_tree_make(inner_right, side_key, side_value, outer));"
      , "  }"
      , "  return pudu_tree_make(left, key, value, right);"
      , "}"
      ])
  , ("tree_find",
      [ "static pudu_tree_node *pudu_tree_find(pudu_tree_node *node, pudu_cell key, const pudu_tree_ops *ops) {"
      , "  while (node != NULL) {"
      , "    int order = ops->order(key, node->key);"
      , "    if (order == 0) return node;"
      , "    node = order < 0 ? node->left : node->right;"
      , "  }"
      , "  return NULL;"
      , "}"
      ])
  , ("tree_insert",
      [ "/* An equal key stays when keep is set and is replaced otherwise; the value"
      , "   is always the new one. */"
      , "static pudu_tree_node *pudu_tree_insert(pudu_tree_node *node, pudu_cell key, pudu_cell value, int keep, const pudu_tree_ops *ops) {"
      , "  pudu_tree_node *left, *right;"
      , "  pudu_cell held, stored;"
      , "  int order;"
      , "  if (node == NULL) return pudu_tree_make(NULL, key, value, NULL);"
      , "  order = ops->order(key, node->key);"
      , "  pudu_tree_open(node, ops, &left, &held, &stored, &right);"
      , "  if (order == 0) {"
      , "    ops->release_value(stored);"
      , "    if (keep) { ops->release_key(key); key = held; } else ops->release_key(held);"
      , "    return pudu_tree_make(left, key, value, right);"
      , "  }"
      , "  if (order < 0) return pudu_tree_balance(pudu_tree_insert(left, key, value, keep, ops), held, stored, right, ops);"
      , "  return pudu_tree_balance(left, held, stored, pudu_tree_insert(right, key, value, keep, ops), ops);"
      , "}"
      ])
  , ("tree_remove",
      [ "static pudu_tree_node *pudu_tree_remove_least(pudu_tree_node *node, pudu_cell *key, pudu_cell *value, const pudu_tree_ops *ops) {"
      , "  pudu_tree_node *left, *right;"
      , "  pudu_cell held, stored;"
      , "  pudu_tree_open(node, ops, &left, &held, &stored, &right);"
      , "  if (left == NULL) { *key = held; *value = stored; return right; }"
      , "  return pudu_tree_balance(pudu_tree_remove_least(left, key, value, ops), held, stored, right, ops);"
      , "}"
      , "static pudu_tree_node *pudu_tree_join(pudu_tree_node *left, pudu_tree_node *right, const pudu_tree_ops *ops) {"
      , "  pudu_cell key, value;"
      , "  if (left == NULL) return right;"
      , "  if (right == NULL) return left;"
      , "  right = pudu_tree_remove_least(right, &key, &value, ops);"
      , "  return pudu_tree_balance(left, key, value, right, ops);"
      , "}"
      , "static pudu_tree_node *pudu_tree_remove_present(pudu_tree_node *node, pudu_cell key, const pudu_tree_ops *ops) {"
      , "  pudu_tree_node *left, *right;"
      , "  pudu_cell held, stored;"
      , "  int order = ops->order(key, node->key);"
      , "  pudu_tree_open(node, ops, &left, &held, &stored, &right);"
      , "  if (order == 0) {"
      , "    ops->release_key(held);"
      , "    ops->release_value(stored);"
      , "    return pudu_tree_join(left, right, ops);"
      , "  }"
      , "  if (order < 0) return pudu_tree_balance(pudu_tree_remove_present(left, key, ops), held, stored, right, ops);"
      , "  return pudu_tree_balance(left, held, stored, pudu_tree_remove_present(right, key, ops), ops);"
      , "}"
      , "/* An absent key leaves the tree as it is, uncopied. */"
      , "static pudu_tree_node *pudu_tree_remove(pudu_tree_node *node, pudu_cell key, const pudu_tree_ops *ops) {"
      , "  if (pudu_tree_find(node, key, ops) == NULL) return node;"
      , "  return pudu_tree_remove_present(node, key, ops);"
      , "}"
      ])
  , ("tree_walk",
      [ "static size_t pudu_tree_walk(pudu_tree_node *node, pudu_tree_node **out, size_t at) {"
      , "  while (node != NULL) {"
      , "    at = pudu_tree_walk(node->left, out, at);"
      , "    out[at++] = node;"
      , "    node = node->right;"
      , "  }"
      , "  return at;"
      , "}"
      , "/* The nodes in ascending order, in a buffer the caller frees. */"
      , "static pudu_tree_node **pudu_tree_nodes(pudu_tree_node *node) {"
      , "  size_t size = pudu_tree_size(node);"
      , "  pudu_tree_node **out;"
      , "  if (size > SIZE_MAX / sizeof *out) pudu_memory_failure();"
      , "  out = malloc((size == 0 ? 1 : size) * sizeof *out);"
      , "  if (out == NULL) pudu_memory_failure();"
      , "  (void)pudu_tree_walk(node, out, 0);"
      , "  return out;"
      , "}"
      ])
  , ("tree_word_algebra",
      [ "typedef struct { pudu_cell key, value; } pudu_word_pair;"
      , "/* Consumes retained pairs; recursion is bounded by the balanced height. */"
      , "static pudu_tree_node *pudu_word_tree(pudu_word_pair *pairs, size_t start, size_t count) {"
      , "  if (count == 0) return NULL;"
      , "  size_t half = count / 2, middle = start + half;"
      , "  pudu_tree_node *left = pudu_word_tree(pairs, start, half);"
      , "  pudu_tree_node *right = pudu_word_tree(pairs, middle + 1, count - half - 1);"
      , "  return pudu_tree_make(left, pairs[middle].key, pairs[middle].value, right);"
      , "}"
      , "/* Typed callers prove UInt64 payloads and operation in 0..3. Inputs are borrowed. */"
      , "static pudu_tree_node *pudu_tree_word_algebra(pudu_tree_node *left, pudu_tree_node *right, const pudu_tree_ops *ops, unsigned operation) {"
      , "  size_t n = pudu_tree_size(left), m = pudu_tree_size(right), capacity;"
      , "  size_t i = 0, j = 0, count = 0;"
      , "  pudu_word_pair *pairs;"
      , "  if (n > SIZE_MAX - m) pudu_memory_failure();"
      , "  capacity = n + m;"
      , "  if (capacity > SIZE_MAX / sizeof *pairs) pudu_memory_failure();"
      , "  pairs = malloc((capacity == 0 ? 1 : capacity) * sizeof *pairs);"
      , "  if (pairs == NULL) pudu_memory_failure();"
      , "  pudu_tree_node **a = pudu_tree_nodes(left), **b = pudu_tree_nodes(right);"
      , "  while (i < n || j < m) {"
      , "    int order = i == n ? 1 : j == m ? -1 : ops->order(a[i]->key, b[j]->key);"
      , "    pudu_tree_node *held = order <= 0 ? a[i] : b[j];"
      , "    uint64_t x = 0, y = 0, word;"
      , "    if (order <= 0) x = a[i++]->value.integer.bits;"
      , "    if (order >= 0) y = b[j++]->value.integer.bits;"
      , "    word = operation == 0 ? (x | y) : operation == 1 ? (x & y) : operation == 2 ? (x & ~y) : (x ^ y);"
      , "    if (word != 0) {"
      , "      pairs[count].key = ops->retain_key(held->key);"
      , "      pairs[count++].value.integer = pudu_make(word, 0);"
      , "    }"
      , "  }"
      , "  pudu_tree_node *result = pudu_word_tree(pairs, 0, count);"
      , "  free(a); free(b); free(pairs);"
      , "  return result;"
      , "}" ])
  , ("tree_word_predicate",
      [ "static int pudu_tree_word_predicate(pudu_tree_node *left, pudu_tree_node *right, const pudu_tree_ops *ops, unsigned operation) {"
      , "  size_t count = pudu_tree_size(left);"
      , "  pudu_tree_node **nodes = pudu_tree_nodes(left);"
      , "  int answer = 1;"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    pudu_tree_node *found = pudu_tree_find(right, nodes[i]->key, ops);"
      , "    uint64_t a = nodes[i]->value.integer.bits, b = found == NULL ? 0 : found->value.integer.bits;"
      , "    if ((operation == 0 ? (a & ~b) : (a & b)) != 0) { answer = 0; break; }"
      , "  }"
      , "  free(nodes);"
      , "  return answer;", "}" ])
  , ("tree_word_count",
      [ "static pudu_wide_int pudu_tree_word_count(pudu_tree_node *root) {"
      , "  size_t count = pudu_tree_size(root);"
      , "  pudu_tree_node **nodes = pudu_tree_nodes(root);"
      , "  pudu_word128 total = {0, 0};"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    uint64_t word = nodes[i]->value.integer.bits, bits = 0;"
      , "    while (word != 0) { word &= word - UINT64_C(1); ++bits; }"
      , "    total = pudu_word128_add(total, (pudu_word128){bits, 0}).value;"
      , "  }"
      , "  free(nodes);"
      , "  return pudu_wide_make(total, 0);", "}" ])
  , ("tree_word_members",
      [ "static pudu_box *pudu_tree_word_members(pudu_tree_node *root) {"
      , "  size_t count = pudu_tree_size(root), length = 0, at = 0;"
      , "  pudu_tree_node **nodes = pudu_tree_nodes(root);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    uint64_t word = nodes[i]->value.integer.bits;"
      , "    while (word != 0) {"
      , "      if (length == SIZE_MAX) pudu_memory_failure();"
      , "      ++length; word &= word - UINT64_C(1);"
      , "    }"
      , "  }"
      , "  pudu_box *array = pudu_array_new(length);"
      , "  pudu_items *items = array->fields[0].items;"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    uint64_t word = nodes[i]->value.integer.bits, base = nodes[i]->key.integer.bits << 6;"
      , "    for (unsigned bit = 0; bit < 64; ++bit)"
      , "      if ((word & (UINT64_C(1) << bit)) != 0) items->cells[at++].integer = pudu_make(base | (uint64_t)bit, 0);"
      , "  }"
      , "  items->length = length;"
      , "  free(nodes);"
      , "  return array;", "}" ])
  ]

treeRuntimeDependencies :: Text -> [Text]
treeRuntimeDependencies name = maybe [] id (lookup name
  [ ("tree", [])
  , ("tree_retain", ["tree"])
  , ("tree_node", ["tree", "memory_failure"])
  , ("tree_build", ["tree_node", "tree_retain"])
  , ("tree_find", ["tree"])
  , ("tree_insert", ["tree_build"])
  , ("tree_remove", ["tree_build", "tree_find"])
  , ("tree_walk", ["tree", "memory_failure"])
  , ("tree_word_algebra", ["tree_node", "tree_walk", "make"])
  , ("tree_word_predicate", ["tree_walk", "tree_find"])
  , ("tree_word_count", ["tree_walk", "word128_add", "wide_make"])
  , ("tree_word_members", ["tree_walk", "array", "make"])
  ])
